insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se subsidiariamente, no que couber, as disposições da Lei da Ação Civil Pública.', '["Aplicação subsidiária da Lei da Ação Civil Pública."]'::jsonb, '["Subsidiária, no que couber."]'::jsonb, 'Lacunas do rito coletivo do Estatuto são supridas pela Lei da Ação Civil Pública.', '["Assertiva que afasta a Lei da Ação Civil Pública das ações do Estatuto erra."]'::jsonb, '[]'::jsonb, '["Art. 212"]'::jsonb, 'under_review', 'claude'
