insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O capítulo dispõe sobre crimes praticados contra a criança e o adolescente, por ação ou omissão, sem prejuízo do disposto na legislação penal.', '["Crimes contra a criança e o adolescente.","Sem prejuízo da legislação penal."]'::jsonb, '["Aplica-se sem excluir o Código Penal."]'::jsonb, 'Um mesmo fato pode ser punido pelo Estatuto e pelo Código Penal, conforme o tipo.', '["Assertiva que afasta a legislação penal comum dos crimes contra a criança erra."]'::jsonb, '[]'::jsonb, '["Art. 226"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-225'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicam-se aos crimes do Estatuto a Parte Geral do Código Penal e, quanto ao processo, o Código de Processo Penal. Aos crimes cometidos contra a criança e o adolescente, independentemente da pena prevista, não se aplica a lei dos juizados especiais criminais. Nos casos de violência doméstica e familiar contra a criança e o adolescente, é vedada a aplicação de penas de cesta básica ou de prestação pecuniária, bem como a substituição de pena que implique o pagamento isolado de multa.', '["Código Penal e Código de Processo Penal aplicam-se.","Não se aplica a lei dos juizados especiais.","Vedadas cesta básica, prestação pecuniária e pagamento isolado de multa em violência doméstica."]'::jsonb, '["ATUALIZAÇÃO: os §§1º e 2º foram incluídos por leis posteriores.","Lei dos Juizados Especiais NÃO se aplica aos crimes contra a criança, qualquer que seja a pena."]'::jsonb, 'O crime com pena baixa contra a criança não vai ao juizado especial.', '["Assertiva que aplica a transação penal aos crimes do Estatuto de menor pena erra."]'::jsonb, '[]'::jsonb, '["Art. 227"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-226'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aumenta-se a pena de um terço a dois terços se o agente comete crime previsto no capítulo mediante utilização de modulador de proxy ou técnica de mascaramento, ocultação, falsificação, alteração ou anonimização de endereço IP ou de qualquer outro identificador digital, por meio de software, programa, ferramenta ou navegador, com o objetivo de impedir ou dificultar sua identificação.', '["Causa de aumento de um terço a dois terços.","Uso de proxy e técnicas de anonimização.","Finalidade de dificultar a identificação."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Aumento de um terço a dois terços."]'::jsonb, 'O agente que usa técnica de anonimização de IP para praticar o crime tem a pena aumentada.', '["Assertiva que fixa o aumento em até metade erra: é de um terço a dois terços."]'::jsonb, '[]'::jsonb, '["Art. 241-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-226-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os crimes definidos no Estatuto são de ação pública incondicionada.', '["Ação pública incondicionada."]'::jsonb, '["Não dependem de representação da vítima."]'::jsonb, 'O Ministério Público denuncia sem precisar de representação.', '["Assertiva que condiciona os crimes do Estatuto à representação erra."]'::jsonb, '[]'::jsonb, '["Art. 226"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-227'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os efeitos da condenação de perda de cargo, função ou mandato, para os crimes do Estatuto praticados por servidores públicos com abuso de autoridade, ficam condicionados à ocorrência de reincidência. A perda do cargo, do mandato ou da função, nesse caso, independe da pena aplicada na reincidência.', '["Perda do cargo condicionada à reincidência.","Independe da pena aplicada na reincidência."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Exige REINCIDÊNCIA."]'::jsonb, 'O servidor reincidente perde o cargo, qualquer que seja a pena da reincidência.', '["Assertiva que dispensa a reincidência para a perda do cargo nesses crimes erra."]'::jsonb, '[]'::jsonb, '["Art. 226"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-227-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança ou o adolescente vítima ou testemunha de violência sexual tem direito a atendimento psicológico e psicossocial, de forma individual, especializada, contínua e integral. O atendimento abrange os impactos emocionais, sociais e cognitivos decorrentes da exposição indevida da vítima.', '["Atendimento psicológico e psicossocial.","Individual, especializado, contínuo e integral.","Abrange impactos emocionais, sociais e cognitivos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Alcança vítima E testemunha."]'::jsonb, 'A criança testemunha de violência sexual recebe acompanhamento psicológico contínuo.', '["Assertiva que restringe o atendimento à vítima direta e exclui a testemunha erra."]'::jsonb, '[]'::jsonb, '["Art. 227-C"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-227-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O agente que causar lesão corporal ou praticar violência física, sexual ou psicológica contra criança ou adolescente é obrigado a cobrir integralmente os custos do tratamento da vítima, incluído o ressarcimento ao SUS pelos serviços prestados, sendo os valores arrecadados destinados ao Fundo de Saúde do ente federado responsável pela unidade que realizou o atendimento.', '["Agressor cobre os custos do tratamento.","Ressarcimento ao SUS.","Valores destinados ao Fundo de Saúde."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Ressarcimento INTEGRAL, inclusive ao SUS."]'::jsonb, 'O agressor ressarce o SUS pelo atendimento à criança que feriu.', '["Assertiva que isenta o agressor de ressarcir o SUS erra."]'::jsonb, '[]'::jsonb, '["Art. 227-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-227-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime o encarregado de serviço ou dirigente de estabelecimento de atenção à saúde de gestante que deixa de manter registro das atividades desenvolvidas, na forma e prazo do art. 10, ou de fornecer à parturiente, por ocasião da alta, a declaração de nascimento com as intercorrências do parto e do desenvolvimento do neonato. A pena é de detenção de seis meses a dois anos, e, se o crime é culposo, detenção de dois a seis meses ou multa.', '["Omissão de registro e de declaração de nascimento.","Detenção de seis meses a dois anos.","Modalidade culposa com pena menor."]'::jsonb, '["Detenção de seis meses a dois anos.","Culposo: detenção de dois a seis meses, ou multa."]'::jsonb, 'O dirigente da maternidade que não mantém os prontuários comete esse crime.', '["Assertiva que torna atípica a modalidade culposa erra."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-228'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime o médico, enfermeiro ou dirigente de estabelecimento de atenção à saúde de gestante que deixa de identificar corretamente o neonato e a parturiente por ocasião do parto, ou de proceder aos exames referidos no art. 10. A pena é de detenção de seis meses a dois anos, e, se o crime é culposo, detenção de dois a seis meses ou multa.', '["Falha na identificação do neonato e da parturiente.","Omissão dos exames do art. 10.","Forma culposa."]'::jsonb, '["Pena: detenção de seis meses a dois anos.","Forma culposa: dois a seis meses ou multa."]'::jsonb, 'A maternidade que troca a pulseira de identificação comete o crime.', '["Assertiva que pune só a modalidade dolosa erra: há modalidade culposa."]'::jsonb, '[]'::jsonb, '["Art. 228"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-229'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem priva a criança ou o adolescente de sua liberdade, apreendendo-o sem estar em flagrante de ato infracional ou sem ordem escrita da autoridade judiciária competente. A pena é de detenção de seis meses a dois anos. Incide na mesma pena quem procede à apreensão sem observância das formalidades legais, e a lei dos juizados especiais não se aplica ao crime.', '["Apreensão ilegal.","Detenção de seis meses a dois anos.","Também a apreensão sem as formalidades.","Sem juizado especial."]'::jsonb, '["Não se aplica a lei dos juizados especiais ao crime."]'::jsonb, 'O policial que apreende o adolescente sem flagrante nem ordem escrita comete o crime.', '["Assertiva que aplica a transação penal ao crime de apreensão ilegal erra."]'::jsonb, '[]'::jsonb, '["Art. 106"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-230'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime a autoridade policial responsável pela apreensão de criança ou adolescente que deixa de fazer imediata comunicação à autoridade judiciária competente e à família do apreendido ou à pessoa por ele indicada. A pena é de detenção de seis meses a dois anos.', '["Omissão da comunicação imediata.","Detenção de seis meses a dois anos."]'::jsonb, '["Comunicar ao juiz E à família."]'::jsonb, 'O delegado que não avisa a família do adolescente apreendido pratica o crime.', '["Assertiva que exige comunicação apenas ao juiz erra: também à família."]'::jsonb, '[]'::jsonb, '["Art. 107"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-231'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime a autoridade competente que, sem justa causa, deixa de ordenar a imediata liberação de criança ou adolescente tão logo tenha conhecimento da ilegalidade da apreensão. A pena é de detenção de seis meses a dois anos.', '["Omissão de liberação imediata.","Detenção de seis meses a dois anos."]'::jsonb, '["Exige conhecimento da ilegalidade e ausência de justa causa."]'::jsonb, 'O juiz que mantém o adolescente apreendido ilegalmente comete o crime.', '["Assertiva que pune a liberação imediata da apreensão ilegal erra."]'::jsonb, '[]'::jsonb, '["Art. 230"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-234'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem descumpre, injustificadamente, prazo fixado no Estatuto em benefício de adolescente privado de liberdade. A pena é de detenção de seis meses a dois anos.', '["Descumprimento injustificado de prazo.","Beneficia adolescente privado de liberdade."]'::jsonb, '["O prazo é em benefício do adolescente privado de liberdade."]'::jsonb, 'O servidor que retarda a liberação além do prazo comete o crime.', '["Assertiva que pune qualquer atraso de prazo, mesmo justificado, erra."]'::jsonb, '[]'::jsonb, '["Art. 183"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-235'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem impede ou embaraça a ação de autoridade judiciária, membro do Conselho Tutelar ou representante do Ministério Público no exercício de função prevista no Estatuto. A pena é de detenção de seis meses a dois anos.', '["Impedir ou embaraçar a ação de juiz, conselheiro ou promotor.","Detenção de seis meses a dois anos."]'::jsonb, '["Protege três agentes: juiz, conselheiro tutelar e promotor."]'::jsonb, 'Quem impede o conselheiro tutelar de entrar na casa para vistoriar comete o crime.', '["Assertiva que exclui o conselheiro tutelar da proteção do tipo erra."]'::jsonb, '[]'::jsonb, '["Art. 136"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-236'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem subtrai criança ou adolescente ao poder de quem o tem sob sua guarda em virtude de lei ou ordem judicial, com o fim de colocação em lar substituto. A pena é de reclusão de dois a seis anos, e multa.', '["Subtração de quem está sob guarda legal ou judicial.","Finalidade de colocação em lar substituto.","Reclusão de dois a seis anos, e multa."]'::jsonb, '["Exige o FIM de colocação em lar substituto."]'::jsonb, 'Quem retira a criança do guardião para entregá-la a outra família pratica o crime.', '["Assertiva que dispensa a finalidade de colocação em lar substituto erra."]'::jsonb, '[]'::jsonb, '["Art. 238"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-237'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem promete ou efetiva a entrega de filho ou pupilo a terceiro, mediante paga ou recompensa. A pena é de reclusão de um a quatro anos, e multa. Incide nas mesmas penas quem oferece ou efetiva a paga ou recompensa.', '["Promessa ou entrega de filho mediante paga.","Reclusão de um a quatro anos, e multa.","Quem paga também responde."]'::jsonb, '["Quem OFERECE a recompensa responde na mesma pena."]'::jsonb, 'A mãe que entrega o filho em troca de dinheiro e o comprador praticam o crime.', '["Assertiva que isenta quem oferece a recompensa erra."]'::jsonb, '[]'::jsonb, '["Art. 237"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-238'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem promove ou auxilia a efetivação de ato destinado ao envio de criança ou adolescente para o exterior com inobservância das formalidades legais ou com o fito de obter lucro. A pena é de reclusão de quatro a seis anos, e multa. Se há emprego de violência, grave ameaça ou fraude, a pena é de reclusão de seis a oito anos, além da pena correspondente à violência.', '["Envio ilegal ou lucrativo ao exterior.","Reclusão de quatro a seis anos, e multa.","Forma qualificada com violência, grave ameaça ou fraude."]'::jsonb, '["Qualificadora: seis a oito anos, somada à pena da violência."]'::jsonb, 'Quem leva criança ao exterior sem as formalidades legais, visando lucro, comete o crime.', '["Assertiva que fixa pena de detenção para o crime de envio ao exterior erra: é reclusão."]'::jsonb, '[]'::jsonb, '["Art. 85"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-239'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem produz, reproduz, dirige, fotografa, filma ou registra, por qualquer meio, conteúdo de violência sexual contra criança ou adolescente. A pena é de reclusão de quatro a dez anos, e multa. Incorre nas mesmas penas quem financia, agencia, facilita, recruta, coage ou intermedeia a participação da vítima no conteúdo, quem com ela contracena, e quem exibe ou transmite o conteúdo em tempo real, entre outras condutas.', '["Produção do conteúdo de violência sexual.","Reclusão de quatro a dez anos, e multa.","Intermediação, contracenação e transmissão em tempo real."]'::jsonb, '["ATUALIZAÇÃO: a redação foi atualizada para a expressão \"violência sexual\" por lei posterior.","Quem contracena com a vítima responde na mesma pena."]'::jsonb, 'Quem filma cena de violência sexual contra criança comete o crime.', '["Assertiva que isenta quem contracena com a vítima erra."]'::jsonb, '[]'::jsonb, '["Art. 241-E"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-240'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem vende ou expõe à venda fotografia, vídeo ou outro registro que contenha violência sexual contra criança ou adolescente. A pena é de reclusão de quatro a dez anos, e multa, além da perda de bens e valores recebidos em favor do Fundo dos Direitos da Criança e do Adolescente. A pena aumenta de um terço se a venda ocorre por meio de tecnologias da informação e comunicação.', '["Venda ou exposição à venda.","Reclusão de quatro a dez anos, e multa.","Perda de bens em favor do Fundo.","Aumento de um terço se por meios tecnológicos."]'::jsonb, '["ATUALIZAÇÃO: o aumento de um terço para uso de tecnologia foi incluído por lei posterior."]'::jsonb, 'Quem vende vídeos desse tipo pela internet tem a pena aumentada.', '["Assertiva que dispensa a perda de bens em favor do Fundo erra."]'::jsonb, '[]'::jsonb, '["Art. 241-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-241'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem oferece, troca, disponibiliza, transmite, distribui, publica ou divulga, por qualquer meio, inclusive sistema de informática, fotografia, vídeo ou outro registro que contenha violência sexual contra criança ou adolescente. A pena é de reclusão de quatro a dez anos, e multa. Incorre nas mesmas penas quem assegura os meios ou serviços para o armazenamento do material e quem assegura o acesso por rede de computadores, ficando as condutas dos provedores sujeitas à ciência de ilicitude e à notificação oficial.', '["Oferecer, trocar, distribuir e divulgar.","Reclusão de quatro a dez anos, e multa.","Responsabilidade de quem assegura armazenamento e acesso."]'::jsonb, '["Provedor responde se, notificado oficialmente, não desabilitar o acesso ao conteúdo ilícito."]'::jsonb, 'Quem compartilha o vídeo em grupo de mensagens comete o crime.', '["Assertiva que pune apenas a produção do material, e não a divulgação, erra."]'::jsonb, '[]'::jsonb, '["Art. 241-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-241-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem adquire, possui, armazena ou solicita, por qualquer meio, fotografia, vídeo ou outro registro que contenha violência sexual contra criança ou adolescente. A pena é de reclusão de três a seis anos, e multa, diminuída de um sexto a um terço se for pequena a quantidade de material. Não há crime se a posse ou o armazenamento tem a finalidade de comunicar o fato às autoridades, quando feita por agentes públicos, membros de entidades de denúncia ou representantes de provedores.', '["Posse e armazenamento do material.","Reclusão de três a seis anos, e multa.","Diminuição de um sexto a um terço se pequena quantidade.","Excludente para a comunicação às autoridades."]'::jsonb, '["Posse com o fim de comunicar às autoridades NÃO é crime nas hipóteses legais.","Pena menor do que a de distribuição."]'::jsonb, 'Quem guarda o material para entregá-lo à polícia, nas hipóteses legais, não comete o crime.', '["Assertiva que pune igualmente a posse com fim de denúncia às autoridades erra."]'::jsonb, '[]'::jsonb, '["Art. 241-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-241-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem simula a participação de criança ou adolescente em conteúdo de violência sexual por meio de adulteração, montagem ou modificação de fotografia, vídeo ou outra representação visual, mediante qualquer recurso tecnológico que altere imagem ou voz da vítima, inclusive com inteligência artificial. A pena é de reclusão de três a cinco anos, e multa. Incorre nas mesmas penas quem vende, expõe, disponibiliza, distribui, publica, divulga, adquire, possui ou armazena esse material.', '["Montagem e adulteração, inclusive com inteligência artificial.","Reclusão de três a cinco anos, e multa.","Mesma pena para quem comercializa, divulga ou possui o material."]'::jsonb, '["ATUALIZAÇÃO: inclusão expressa da inteligência artificial por lei posterior.","Não exige participação real da criança."]'::jsonb, 'Quem usa inteligência artificial para criar imagem falsa desse tipo comete o crime.', '["Assertiva que exige a participação real da criança no conteúdo simulado erra."]'::jsonb, '[]'::jsonb, '["Art. 241-E"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-241-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem alicia, assedia, convida, instiga ou constrange, por qualquer meio, menor de catorze anos, com o fim de praticar ato libidinoso. A pena é de reclusão de três a cinco anos, e multa, se o fato não constituir crime mais grave. Incorrem nas mesmas penas quem facilita o acesso do menor a material de sexo explícito ou nudez com esse fim e quem o induz a se exibir de forma lasciva ou sexualmente explícita.', '["Aliciamento de menor de catorze anos.","Reclusão de três a cinco anos, e multa.","Subsidiário: só se não houver crime mais grave."]'::jsonb, '["Vítima: menor de CATORZE anos.","Cláusula de subsidiariedade."]'::jsonb, 'Quem aborda criança de dez anos na internet para fim libidinoso comete o crime.', '["Assertiva que alcança o aliciamento de menor de dezoito anos nesse tipo erra: é menor de catorze anos."]'::jsonb, '[]'::jsonb, '["Art. 241-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-241-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para os crimes da lei, considera-se material ou conteúdo de violência sexual contra criança ou adolescente qualquer representação, por qualquer meio, inclusive fotografia, vídeo, imagem digital ou outro registro audiovisual, que envolva criança ou adolescente, real ou fictício, ainda que produzida, manipulada ou gerada com tecnologias digitais, inclusive inteligência artificial, quando retratar atividade sexual explícita, real ou simulada, contiver nudez total ou parcial com finalidade sexual ou libidinosa, ou representar situação semelhante.', '["Definição legal de conteúdo de violência sexual.","Inclui criança real ou fictícia e conteúdo gerado por inteligência artificial.","Atividade sexual explícita ou nudez com finalidade sexual."]'::jsonb, '["ATUALIZAÇÃO: definição ampliada por lei posterior (conteúdo fictício e inteligência artificial)."]'::jsonb, 'A imagem gerada artificialmente com cena sexual envolvendo criança fictícia se enquadra.', '["Assertiva que exclui o conteúdo fictício da definição erra."]'::jsonb, '[]'::jsonb, '["Art. 240"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-241-e'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem vende, fornece, ainda que gratuitamente, ou entrega, de qualquer forma, a criança ou adolescente arma, munição ou explosivo. A pena é de reclusão de três a seis anos.', '["Venda, fornecimento ou entrega de arma, munição ou explosivo.","Reclusão de três a seis anos."]'::jsonb, '["ATUALIZAÇÃO: a pena foi elevada por lei posterior (Estatuto do Desarmamento).","Vale mesmo se for gratuito."]'::jsonb, 'Quem empresta arma a um adolescente comete o crime.', '["Assertiva que exige remuneração para a configuração do crime erra: basta fornecer, ainda que gratuitamente."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-242'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem vende, fornece, serve, ministra ou entrega, ainda que gratuitamente, a criança ou adolescente bebida alcoólica ou, sem justa causa, outros produtos cujos componentes possam causar dependência física ou psíquica. A pena é de detenção de dois a quatro anos, e multa, se o fato não constitui crime mais grave. A pena aumenta de um terço até a metade se a criança ou o adolescente utilizar ou consumir o produto.', '["Fornecimento de bebida alcoólica e produtos que causem dependência.","Detenção de dois a quatro anos, e multa.","Aumento se houver consumo."]'::jsonb, '["ATUALIZAÇÃO: pena alterada por lei posterior; antes era contravenção penal.","Aumento de um terço até a metade se a vítima consumir."]'::jsonb, 'O bar que serve cerveja a um adolescente comete o crime.', '["Assertiva que trata o fornecimento de bebida alcoólica a adolescente como mera contravenção erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-243'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem vende, fornece, ainda que gratuitamente, ou entrega, de qualquer forma, a criança ou adolescente fogos de estampido ou de artifício, exceto os que, pelo reduzido potencial, sejam incapazes de provocar dano físico em caso de utilização indevida. A pena é de detenção de seis meses a dois anos, e multa.', '["Fogos de estampido ou de artifício.","Detenção de seis meses a dois anos, e multa.","Exceção para fogos inofensivos."]'::jsonb, '["Exceção: fogos de reduzido potencial, incapazes de causar dano."]'::jsonb, 'A loja que vende bombinhas a uma criança comete o crime.', '["Assertiva que proíbe a venda de qualquer fogo, mesmo inofensivo, erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-244'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem submete criança ou adolescente à exploração sexual, se o fato não constituir crime mais grave. A pena é de reclusão de quatro a dez anos, e multa, além da perda de bens e valores utilizados na prática criminosa em favor do Fundo dos Direitos da Criança e do Adolescente do estado ou do Distrito Federal onde foi cometido o crime. Incorrem nas mesmas penas o proprietário, o gerente ou o responsável pelo local onde se verifique a submissão, sendo efeito obrigatório da condenação a cassação da licença de localização e de funcionamento.', '["Exploração sexual de criança ou adolescente.","Reclusão de quatro a dez anos, e multa.","Perda de bens em favor do Fundo.","Responsabilidade do dono ou gerente do local e cassação da licença."]'::jsonb, '["Efeito obrigatório: cassação da licença de funcionamento do local.","Subsidiário: só se não houver crime mais grave."]'::jsonb, 'O dono de casa noturna que permite a exploração sexual de adolescente responde pelo crime.', '["Assertiva que isenta o proprietário do local onde ocorre a exploração erra."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-244-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete crime quem corrompe ou facilita a corrupção de menor de dezoito anos, com ele praticando infração penal ou induzindo-o a praticá-la. A pena é de reclusão de um a quatro anos. Incorre nas mesmas penas quem pratica as condutas por meios eletrônicos, inclusive salas de bate-papo da internet. A pena aumenta de um terço se a infração cometida ou induzida estiver no rol dos crimes hediondos.', '["Corrupção de menor.","Reclusão de um a quatro anos.","Meios eletrônicos incluídos.","Aumento de um terço se a infração for hedionda."]'::jsonb, '["Menor de DEZOITO anos.","Aumento de um terço se a infração for crime hediondo."]'::jsonb, 'O adulto que pratica roubo com adolescente corrompe o menor.', '["Assertiva que fixa a vítima como menor de catorze anos erra: é menor de dezoito anos."]'::jsonb, '[{"termo":"Corrupção de menores","significado":"Praticar infração penal com menor de dezoito anos ou induzi-lo a praticá-la."}]'::jsonb, '["Lei dos Crimes Hediondos"]'::jsonb, 'under_review', 'claude'
