insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração o médico, professor ou responsável por estabelecimento de atenção à saúde e de ensino fundamental, pré-escola ou creche que deixa de comunicar à autoridade competente os casos de suspeita ou confirmação de maus-tratos contra criança ou adolescente. A pena é de multa de três a vinte salários de referência, aplicando-se o dobro em caso de reincidência.', '["Omissão de comunicar maus-tratos.","Médico, professor ou responsável por estabelecimento.","Multa de três a vinte salários de referência, dobrada na reincidência."]'::jsonb, '["Basta a SUSPEITA de maus-tratos.","É infração administrativa com multa."]'::jsonb, 'O professor que percebe sinais de agressão e nada comunica sujeita-se à multa.', '["Assertiva que exige confirmação dos maus-tratos para o dever de comunicar erra: basta a suspeita."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
