insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem, sendo responsável ou funcionário de entidade de atendimento, impede o exercício de direitos do adolescente privado de liberdade, como peticionar a autoridades e receber visitas. A pena é de multa de três a vinte salários de referência, aplicando-se o dobro em caso de reincidência.', '["Impedir direitos do adolescente privado de liberdade.","Multa de três a vinte salários de referência."]'::jsonb, '["Dobro na reincidência."]'::jsonb, 'O diretor que proíbe o contato com o defensor sofre a multa.', '["Assertiva que prevê pena de reclusão para essa infração erra: é multa."]'::jsonb, '[]'::jsonb, '["Art. 124"]'::jsonb, 'under_review', 'claude'
