insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem divulga, total ou parcialmente, sem autorização devida, por qualquer meio de comunicação, nome, ato ou documento de procedimento policial, administrativo ou judicial relativo a criança ou adolescente a quem se atribua ato infracional. A pena é de multa de três a vinte salários de referência, aplicando-se o dobro em caso de reincidência. Incorre na mesma pena quem exibe ou transmite imagem, vídeo ou corrente de vídeo da criança ou adolescente de forma a permitir sua identificação.', '["Divulgação sem autorização.","Exibição de imagem que permita identificação.","Multa de três a vinte salários de referência."]'::jsonb, '["Também pune a exibição de imagem que identifique o adolescente.","O veículo de comunicação pode sofrer apreensão da publicação ou suspensão da programação."]'::jsonb, 'A emissora que mostra o rosto do adolescente apreendido comete a infração.', '["Assertiva que permite divulgar a imagem desde que se omita o nome erra, se a imagem permitir a identificação."]'::jsonb, '[]'::jsonb, '["Art. 143"]'::jsonb, 'under_review', 'claude'
