insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem hospeda criança ou adolescente desacompanhado dos pais ou responsável, ou sem autorização escrita destes ou da autoridade judiciária, em hotel, pensão, motel ou congênere. A pena é de multa. Em caso de reincidência, a autoridade judiciária pode determinar o fechamento do estabelecimento por até quinze dias; se comprovada reincidência em período inferior a trinta dias, o estabelecimento é definitivamente fechado e tem a licença cassada.', '["Hospedagem irregular.","Multa.","Fechamento por até quinze dias na reincidência.","Fechamento definitivo se reincidir em menos de trinta dias."]'::jsonb, '["Quinze dias na reincidência; fechamento definitivo se for em menos de trinta dias."]'::jsonb, 'O motel que hospeda adolescente desacompanhado sofre multa.', '["Assertiva que prevê fechamento por trinta dias na primeira reincidência erra: são até quinze dias."]'::jsonb, '[]'::jsonb, '["Art. 82"]'::jsonb, 'under_review', 'claude'
