select u.id, u.content_sha256, 'Comete a infração quem transmite, por rádio ou televisão, espetáculo em horário diverso do autorizado ou sem aviso de sua classificação. A pena é de multa de vinte a cem salários de referência; duplicada em caso de reincidência, a autoridade judiciária pode determinar a suspensão da programação da emissora por até dois dias.', '["Transmissão em horário inadequado ou sem aviso de classificação.","Multa de vinte a cem salários de referência.","Suspensão da programação por até dois dias na reincidência."]'::jsonb, '["Suspensão por até dois dias na reincidência.","Dispositivo foi objeto de decisão do STF sobre classificação indicativa."]'::jsonb, 'A emissora que transmite programa sem aviso de classificação sofre multa.', '["Assertiva que prevê suspensão da emissora por trinta dias erra: são até dois dias."]'::jsonb, '[]'::jsonb, '["Art. 76"]'::jsonb, 'under_review', 'claude'
