insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Comete a infração quem descumpre a proibição de vender bebida alcoólica a criança ou adolescente, prevista no inciso II do art. 81. A pena é de multa de três mil a dez mil reais, com a medida administrativa de interdição do estabelecimento comercial até o recolhimento da multa aplicada.', '["Venda de bebida alcoólica a criança ou adolescente.","Multa de três mil a dez mil reais.","Interdição até o recolhimento da multa."]'::jsonb, '["ATUALIZAÇÃO: infração administrativa incluída por lei posterior.","Interdição até o recolhimento da multa."]'::jsonb, 'O comércio que vende cerveja a adolescente é multado e pode ser interditado.', '["Assertiva que dispensa a interdição enquanto a multa não for paga erra."]'::jsonb, '[]'::jsonb, '["Art. 81"]'::jsonb, 'under_review', 'claude'
