on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os contribuintes podem efetuar doações aos Fundos dos Direitos da Criança e do Adolescente nacional, distrital, estaduais ou municipais, devidamente comprovadas, deduzidas integralmente do imposto de renda, dentro de limites: um por cento do imposto devido pelas pessoas jurídicas tributadas com base no lucro real e seis por cento do imposto apurado pelas pessoas físicas na Declaração de Ajuste Anual. As doações têm regras específicas de comprovação e fiscalização.', '["Doações aos Fundos dos Direitos.","Dedução do imposto de renda.","Limite de um por cento para pessoa jurídica no lucro real.","Limite de seis por cento para pessoa física."]'::jsonb, '["Limite de UM por cento (pessoa jurídica) e SEIS por cento (pessoa física).","ATUALIZAÇÃO: regras de dedução alteradas por leis posteriores; confirme a vigência na legislação tributária."]'::jsonb, 'A empresa tributada pelo lucro real doa ao fundo municipal e deduz do imposto, no limite legal.', '["Assertiva que permite dedução ilimitada das doações aos fundos erra."]'::jsonb, '[]'::jsonb, '["Art. 260-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa física pode optar pela doação aos Fundos diretamente em sua Declaração de Ajuste Anual, com dedução limitada ao percentual previsto sobre o imposto apurado. A dedução está sujeita ao limite de seis por cento do imposto de renda apurado e não se aplica à pessoa que usa o modelo simplificado, entre outras regras.', '["Doação direta na declaração.","Limite de seis por cento.","Regras específicas de aplicação."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior; os percentuais do §1º variaram ao longo dos exercícios.","Limite global de seis por cento."]'::jsonb, 'O contribuinte destina parte do imposto ao fundo na própria declaração.', '["Assertiva que fixa limite superior a seis por cento para a dedução da pessoa física erra."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A doação das pessoas jurídicas pode ser deduzida do imposto devido no trimestre, para quem apura o imposto trimestralmente, ou do imposto devido mensalmente e no ajuste anual, para quem apura anualmente. A doação deve ser efetuada dentro do período a que se refere a apuração do imposto.', '["Dedução trimestral ou mensal e anual.","Doação no período da apuração."]'::jsonb, '["A doação precisa ocorrer dentro do período da apuração."]'::jsonb, 'A empresa que apura por trimestre deduz no próprio trimestre da doação.', '["Assertiva que permite doar após o período de apuração e ainda deduzir erra."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As doações podem ser efetuadas em espécie ou em bens. As doações em espécie devem ser depositadas em conta específica, em instituição financeira pública, vinculada ao respectivo fundo.', '["Doação em espécie ou em bens.","Conta específica em instituição financeira pública."]'::jsonb, '["Conta ESPECÍFICA em instituição financeira PÚBLICA."]'::jsonb, 'A doação em dinheiro é depositada na conta do fundo no banco público.', '["Assertiva que permite depósito em banco privado erra."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos responsáveis pela administração das contas dos Fundos devem emitir recibo em favor do doador, assinado por pessoa competente e pelo presidente do Conselho correspondente, especificando número de ordem, dados do emitente e do doador, data e valor efetivamente recebido e o ano-calendário da doação.', '["Recibo assinado pelo responsável e pelo presidente do Conselho.","Dados do emitente, do doador, da data, do valor e do ano-calendário."]'::jsonb, '["Recibo com assinatura do presidente do Conselho."]'::jsonb, 'O doador recebe recibo do fundo para comprovar a dedução.', '["Assertiva que dispensa a assinatura do presidente do Conselho no recibo erra."]'::jsonb, '[]'::jsonb, '["Art. 260-F"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-d'
