insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os órgãos responsáveis pela administração das contas dos Fundos devem manter conta bancária específica destinada exclusivamente a gerir os recursos do Fundo, manter controle das doações recebidas e informar anualmente à Receita Federal as doações recebidas mês a mês, identificando por doador o nome, o CNPJ ou CPF e o valor doado, em espécie ou em bens.', '["Conta bancária exclusiva.","Controle das doações.","Informação anual à Receita Federal."]'::jsonb, '["Informação anual à Receita, mês a mês."]'::jsonb, 'O fundo informa à Receita todas as doações do ano, por doador.', '["Assertiva que dispensa a informação à Receita Federal erra."]'::jsonb, '[]'::jsonb, '["Art. 260-H"]'::jsonb, 'under_review', 'claude'
