insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os Conselhos dos Direitos da Criança e do Adolescente divulgam amplamente à sociedade o calendário de suas reuniões, as ações prioritárias para aplicação das políticas, os requisitos para a apresentação de projetos a serem beneficiados com recursos dos Fundos, a relação dos projetos aprovados em cada ano e o valor dos recursos previstos, entre outras informações.', '["Transparência dos Conselhos.","Divulgação de reuniões, prioridades e projetos aprovados."]'::jsonb, '["Dever de ampla divulgação."]'::jsonb, 'O Conselho publica a lista dos projetos beneficiados no ano.', '["Assertiva que dispensa a divulgação dos projetos aprovados erra."]'::jsonb, '[]'::jsonb, '["Art. 260-J"]'::jsonb, 'under_review', 'claude'
