select u.id, u.content_sha256, 'A Secretaria de Direitos Humanos da Presidência da República encaminha à Receita Federal, até trinta e um de outubro de cada ano, arquivo eletrônico com a relação atualizada dos Fundos dos Direitos da Criança e do Adolescente, com os números de CNPJ e das contas bancárias específicas em instituições financeiras públicas.', '["Envio anual à Receita Federal até trinta e um de outubro.","Relação dos Fundos com CNPJ e contas bancárias."]'::jsonb, '["Prazo: até trinta e um de outubro de cada ano.","A estrutura administrativa citada foi reorganizada desde a edição da lei."]'::jsonb, 'Cada ano, o órgão federal competente envia à Receita a lista de fundos habilitados a receber doações.', '["Assertiva que fixa o envio até trinta de junho erra: é até trinta e um de outubro."]'::jsonb, '[]'::jsonb, '["Art. 260"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-260-k'
