select u.id, u.content_sha256, 'O poder público faz periodicamente ampla divulgação dos direitos da criança e do adolescente nos meios de comunicação social. A divulgação é veiculada em linguagem clara, compreensível e adequada a crianças e adolescentes, especialmente às crianças com idade inferior a seis anos.', '["Divulgação periódica nos meios de comunicação.","Linguagem adequada, especialmente a crianças menores de seis anos."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Atenção às crianças menores de seis anos."]'::jsonb, 'A campanha pública usa linguagem adequada aos pequenos.', '["Assertiva que dispensa a adequação da linguagem ao público infantil erra."]'::jsonb, '[]'::jsonb, '["Art. 265"]'::jsonb, 'under_review', 'claude'
